@startuml

class Company {
  + Name : string
}

class Customer {
  + Address : string
  + VATNumber : string
  + HeadOfficeAddress : string
}

class Product {
  + Name : string
  + StockLevel : int
}

class Order {
  + OrderDate : date
  + PaymentDate : date
  + IsPaid : boolean
}

class OrderLine {
  + Quantity : int
  + IsShipped : boolean
}

class Invoice {
  + InvoiceDate : date
}

class Shipment {
  + Status : string
}

class DeliveryService {
  + Name : string
}

class Warehouse {
  + Address : string
}

Company "1" -- "*" Customer
Company "1" -- "*" Product
Company "1" -- "*" Order
Company "1" -- "*" Invoice
Company "1" -- "*" DeliveryService

Customer "1" -- "*" Order
Customer "1" -- "*" Invoice
Customer "1" -- "*" Warehouse : uses
Warehouse "1" -- "*" Order : delivers to

Order "1" *-- "1..*" OrderLine
Order "1" -- "0..1" Invoice
Order "1" -- "0..*" Shipment

Shipment "1" -- "1..*" OrderLine
Shipment "0..1" -- "1" DeliveryService

@enduml

